//! Locating, verifying and loading the oracle fixtures.
//!
//! Every fixture is listed in `tests/fixtures/MANIFEST.tsv` with its size,
//! sha256 and location:
//! - `committed`: lives in `crates/rusolve-ekk/tests/fixtures/<file>`; a
//!   missing or mismatching committed file is a hard failure.
//! - `target`: regenerated by `tools/highs-oracle/gen_fixtures.sh` into
//!   `<repo>/target/highs-fixtures/<file>`. When it has not been generated the
//!   caller gets `None` and a loud SKIP banner on stderr. It is never a
//!   silent pass. Set `RUSOLVE_REQUIRE_TARGET_FIXTURES=1` to make a missing
//!   target fixture a hard failure (CI).
//!
//! Search order for target fixtures: `$RUSOLVE_HIGHS_FIXTURES`, then
//! `<workspace>/target/highs-fixtures`, then (from a git worktree) the main
//! checkout's `target/highs-fixtures`. Any file found is checked against the
//! manifest's byte count and sha256; a mismatch panics (stale fixture:
//! regenerate).
//!
//! `RUSOLVE_FIXTURES_DIR=<dir>` replaces the whole fixture set: the manifest
//! is `<dir>/MANIFEST.tsv` and every fixture, committed or target, is read
//! from `<dir>` only. It is how the port runs against another oracle's output
//! (`ORACLE_HIGHS=1.16.0 gen_fixtures.sh` writes `target/highs-fixtures-1.16.0`).

use std::collections::HashSet;
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{Mutex, OnceLock};

use serde_json::Value;

use super::records::{
    BasisRec, BuildResultRec, HVectorRec, InvertRec, LpRec, MatrixRec, SolveRec, WorkArraysRec,
};
use super::sha256::sha256_hex;

/// Env var: extra directory holding target-only fixtures (searched first).
pub const FIXTURE_DIR_ENV: &str = "RUSOLVE_HIGHS_FIXTURES";
/// Env var: when set to `1`, a missing target-only fixture panics instead of
/// skipping.
pub const REQUIRE_ENV: &str = "RUSOLVE_REQUIRE_TARGET_FIXTURES";

/// Env var: a complete fixture set (its own MANIFEST.tsv) replacing both the
/// committed and the target fixtures.
pub const FIXTURES_ROOT_ENV: &str = "RUSOLVE_FIXTURES_DIR";

/// The HiGHS commit every fixture was generated from (README.md, "Pinned").
pub const PINNED_HIGHS_COMMIT: &str = "73cac48c5340d775a477087198611862559be250";

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Location {
    Committed,
    Target,
}

#[derive(Clone, Debug)]
pub struct ManifestEntry {
    /// Path relative to the fixture root, e.g. `simplex/afiro.dual.jsonl`.
    pub file: String,
    pub bytes: u64,
    pub sha256: String,
    pub location: Location,
}

#[derive(Debug)]
pub struct Manifest {
    pub highs_commit: String,
    pub patch_sha256: String,
    pub entries: Vec<ManifestEntry>,
}

impl Manifest {
    pub fn entry(&self, file: &str) -> Option<&ManifestEntry> {
        self.entries.iter().find(|e| e.file == file)
    }

    /// Entries whose file starts with `prefix` and ends with `suffix`, in
    /// manifest (alphabetical) order.
    pub fn select(&self, prefix: &str, suffix: &str) -> Vec<&ManifestEntry> {
        self.entries
            .iter()
            .filter(|e| e.file.starts_with(prefix) && e.file.ends_with(suffix))
            .collect()
    }

    pub fn committed(&self) -> Vec<&ManifestEntry> {
        self.entries
            .iter()
            .filter(|e| e.location == Location::Committed)
            .collect()
    }
}

/// `crates/rusolve-ekk`.
pub fn crate_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

/// `crates/rusolve-ekk/tests/fixtures`.
pub fn committed_dir() -> PathBuf {
    crate_dir().join("tests").join("fixtures")
}

/// `$RUSOLVE_FIXTURES_DIR`, when set and non-empty.
pub fn fixtures_root() -> Option<PathBuf> {
    std::env::var(FIXTURES_ROOT_ENV)
        .ok()
        .filter(|d| !d.is_empty())
        .map(PathBuf::from)
}

/// Where the manifest and the committed fixtures are read from.
fn manifest_dir() -> PathBuf {
    fixtures_root().unwrap_or_else(committed_dir)
}

/// The repository (workspace) root: two levels above the crate.
pub fn workspace_dir() -> PathBuf {
    crate_dir()
        .parent()
        .and_then(Path::parent)
        .map(Path::to_path_buf)
        .expect("crate dir has no grandparent")
}

/// If the workspace is a git worktree (`.git` is a file `gitdir: <main>/.git/worktrees/<n>`),
/// return the main checkout's root.
fn main_checkout_dir() -> Option<PathBuf> {
    let text = fs::read_to_string(workspace_dir().join(".git")).ok()?;
    let gitdir = PathBuf::from(text.trim().strip_prefix("gitdir:")?.trim());
    // <main>/.git/worktrees/<name> -> <main>
    let dot_git = gitdir.parent()?.parent()?;
    Some(dot_git.parent()?.to_path_buf())
}

/// Directories searched for target-only fixtures, in order.
pub fn target_dirs() -> Vec<PathBuf> {
    if let Some(root) = fixtures_root() {
        return vec![root];
    }
    let mut dirs = Vec::new();
    if let Ok(d) = std::env::var(FIXTURE_DIR_ENV)
        && !d.is_empty()
    {
        dirs.push(PathBuf::from(d));
    }
    dirs.push(workspace_dir().join("target").join("highs-fixtures"));
    if let Some(main) = main_checkout_dir() {
        let d = main.join("target").join("highs-fixtures");
        if !dirs.contains(&d) {
            dirs.push(d);
        }
    }
    dirs
}

fn parse_manifest(text: &str) -> Manifest {
    let mut highs_commit = String::new();
    let mut patch_sha256 = String::new();
    let mut entries = Vec::new();
    for (n, line) in text.lines().enumerate() {
        if let Some(rest) = line.strip_prefix('#') {
            let rest = rest.trim();
            if let Some(c) = rest.strip_prefix("highs_commit ") {
                highs_commit = c.trim().to_string();
            } else if let Some(p) = rest.strip_prefix("patch_sha256 ") {
                patch_sha256 = p.trim().to_string();
            }
            continue;
        }
        if line.trim().is_empty() {
            continue;
        }
        let cols: Vec<&str> = line.split('\t').collect();
        assert_eq!(
            cols.len(),
            4,
            "MANIFEST.tsv line {}: expected 4 tab-separated columns (file, bytes, sha256, location), got {:?}",
            n + 1,
            line
        );
        let location = match cols[3] {
            "committed" => Location::Committed,
            "target" => Location::Target,
            other => panic!("MANIFEST.tsv line {}: unknown location {other:?}", n + 1),
        };
        entries.push(ManifestEntry {
            file: cols[0].to_string(),
            bytes: cols[1]
                .parse()
                .unwrap_or_else(|e| panic!("MANIFEST.tsv line {}: bad byte count: {e}", n + 1)),
            sha256: cols[2].to_string(),
            location,
        });
    }
    assert!(!entries.is_empty(), "MANIFEST.tsv lists no fixtures");
    Manifest {
        highs_commit,
        patch_sha256,
        entries,
    }
}

/// The committed MANIFEST.tsv, parsed once per test binary.
pub fn manifest() -> &'static Manifest {
    static M: OnceLock<Manifest> = OnceLock::new();
    M.get_or_init(|| {
        let path = manifest_dir().join("MANIFEST.tsv");
        let text = fs::read_to_string(&path)
            .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
        parse_manifest(&text)
    })
}

/// Check size + sha256 of a fixture file against its manifest entry. Each
/// path is verified once per test binary.
fn verify(entry: &ManifestEntry, path: &Path, bytes: &[u8]) {
    static DONE: OnceLock<Mutex<HashSet<PathBuf>>> = OnceLock::new();
    let done = DONE.get_or_init(|| Mutex::new(HashSet::new()));
    if done.lock().unwrap().contains(path) {
        return;
    }
    let regen = "regenerate with tools/highs-oracle/gen_fixtures.sh (never hand-edit fixtures)";
    assert_eq!(
        bytes.len() as u64,
        entry.bytes,
        "fixture {} at {}: size {} != MANIFEST.tsv size {}; stale or modified fixture, {regen}",
        entry.file,
        path.display(),
        bytes.len(),
        entry.bytes
    );
    // A `|`-separated sha256 column lists per-platform oracle outputs (macOS
    // libm vs glibc can differ by an ulp in a reported statistic).
    let got = sha256_hex(bytes);
    assert!(
        entry.sha256.split('|').any(|s| s == got),
        "fixture {} at {}: sha256 {} != MANIFEST.tsv sha256 {}; stale or modified fixture, {regen}",
        entry.file,
        path.display(),
        got,
        entry.sha256
    );
    done.lock().unwrap().insert(path.to_path_buf());
}

/// Find a fixture file. `Ok(path)` if present; `Err(reason)` if it is a
/// target-only fixture that has not been generated. Panics if the name is not
/// in the manifest or a committed fixture is missing.
pub fn locate(file: &str) -> Result<PathBuf, String> {
    let m = manifest();
    let entry = m.entry(file).unwrap_or_else(|| {
        panic!("fixture {file:?} is not listed in tests/fixtures/MANIFEST.tsv (typo? see MANIFEST.tsv for the exact names)")
    });
    match entry.location {
        Location::Committed => {
            let p = manifest_dir().join(file);
            assert!(
                p.is_file(),
                "committed fixture {} is missing (expected at {}); restore it from git",
                file,
                p.display()
            );
            Ok(p)
        }
        Location::Target => {
            let dirs = target_dirs();
            for d in &dirs {
                let p = d.join(file);
                if p.is_file() {
                    return Ok(p);
                }
            }
            Err(format!(
                "target-only fixture {file} not found in: {}",
                dirs.iter()
                    .map(|d| d.display().to_string())
                    .collect::<Vec<_>>()
                    .join(", ")
            ))
        }
    }
}

fn skip_banner(test: &str, reason: &str) {
    eprintln!(
        "\n######## SKIPPED, NOT PASSED ########\n\
         # test:    {test}\n\
         # reason:  {reason}\n\
         # fix:     run tools/highs-oracle/gen_fixtures.sh (needs reference/HiGHS),\n\
         #          or set {FIXTURE_DIR_ENV}=<dir with the generated fixtures>.\n\
         #          Set {REQUIRE_ENV}=1 to turn this skip into a failure.\n\
         ####################################\n"
    );
}

fn require_target() -> bool {
    std::env::var(REQUIRE_ENV)
        .map(|v| v == "1")
        .unwrap_or(false)
}

/// A loaded fixture: one parsed JSON value per line.
pub struct Fixture {
    /// Manifest name, e.g. `factor/afiro.jsonl`.
    pub file: String,
    pub path: PathBuf,
    pub location: Location,
    pub records: Vec<Value>,
}

/// Load a fixture. Returns `None` (after printing a SKIP banner) when it is a
/// target-only fixture that has not been generated, unless
/// `RUSOLVE_REQUIRE_TARGET_FIXTURES=1`, in which case it panics.
///
/// Typical use: `let Some(fx) = load("factor/kb2.jsonl") else { return };`
pub fn load(file: &str) -> Option<Fixture> {
    match locate(file) {
        Ok(path) => Some(read_fixture(file, path)),
        Err(reason) => {
            if require_target() {
                panic!("{reason} ({REQUIRE_ENV}=1)");
            }
            let test = std::thread::current()
                .name()
                .unwrap_or("<unnamed>")
                .to_string();
            skip_banner(&test, &reason);
            None
        }
    }
}

/// Load a fixture that must exist (committed fixtures); panics otherwise.
pub fn load_required(file: &str) -> Fixture {
    match locate(file) {
        Ok(path) => read_fixture(file, path),
        Err(reason) => panic!("{reason}"),
    }
}

fn read_fixture(file: &str, path: PathBuf) -> Fixture {
    let entry = manifest()
        .entry(file)
        .expect("located fixture has a manifest entry");
    let bytes = fs::read(&path).unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    verify(entry, &path, &bytes);
    let text =
        std::str::from_utf8(&bytes).unwrap_or_else(|e| panic!("fixture {file} is not UTF-8: {e}"));
    let mut records = Vec::new();
    for (n, line) in text.lines().enumerate() {
        let v: Value = serde_json::from_str(line)
            .unwrap_or_else(|e| panic!("fixture {file} line {}: invalid JSON: {e}", n + 1));
        assert!(
            v.get("t").and_then(Value::as_str).is_some(),
            "fixture {file} line {}: record has no string field \"t\"",
            n + 1
        );
        records.push(v);
    }
    Fixture {
        file: file.to_string(),
        path,
        location: entry.location,
        records,
    }
}

impl Fixture {
    pub fn len(&self) -> usize {
        self.records.len()
    }

    pub fn is_empty(&self) -> bool {
        self.records.is_empty()
    }

    /// Record at 0-based index `i` (file line `i + 1`).
    pub fn rec(&self, i: usize) -> Rec<'_> {
        Rec::new(
            &self.records[i],
            format!(
                "{}:{} [{}]",
                self.file,
                i + 1,
                record_type(&self.records[i])
            ),
        )
    }

    /// All records in file order.
    pub fn recs(&self) -> impl Iterator<Item = Rec<'_>> + '_ {
        (0..self.records.len()).map(move |i| self.rec(i))
    }

    /// All records with `t == ty`, in file order.
    pub fn of_type(&self, ty: &str) -> impl Iterator<Item = Rec<'_>> + '_ {
        let ty = ty.to_string();
        self.recs().filter(move |r| r.t() == ty)
    }

    /// The first record with `t == ty`; panics if there is none.
    pub fn first(&self, ty: &str) -> Rec<'_> {
        self.of_type(ty)
            .next()
            .unwrap_or_else(|| panic!("fixture {}: no record with t={ty:?}", self.file))
    }

    /// Number of records per type, in first-seen order.
    pub fn type_counts(&self) -> Vec<(String, usize)> {
        let mut out: Vec<(String, usize)> = Vec::new();
        for v in &self.records {
            let t = record_type(v);
            match out.iter_mut().find(|(k, _)| k == t) {
                Some((_, c)) => *c += 1,
                None => out.push((t.to_string(), 1)),
            }
        }
        out
    }
}

pub(crate) fn record_type(v: &Value) -> &str {
    v.get("t").and_then(Value::as_str).unwrap_or("?")
}

/// A JSON object from a fixture plus a human-readable location
/// (`file:line [type].path`), used in every panic message.
///
/// Getters decode the oracle encoding: f64 = 16 hex digits of the bit
/// pattern; HighsInt/bool/enum = JSON number; hash = 16 hex digits.
#[derive(Clone)]
pub struct Rec<'a> {
    pub v: &'a Value,
    pub ctx: String,
}

impl<'a> Rec<'a> {
    pub fn new(v: &'a Value, ctx: String) -> Self {
        Rec { v, ctx }
    }

    /// Location of field `key`, for messages: `file:line [type].key`.
    pub fn at(&self, key: &str) -> String {
        format!("{}.{}", self.ctx, key)
    }

    pub fn t(&self) -> &'a str {
        record_type(self.v)
    }

    pub fn has(&self, key: &str) -> bool {
        self.v.get(key).is_some()
    }

    /// The raw JSON value of a field.
    pub fn value(&self, key: &str) -> &'a Value {
        self.v.get(key).unwrap_or_else(|| {
            panic!(
                "{}: missing field (record keys: {})",
                self.at(key),
                self.keys().join(",")
            )
        })
    }

    pub fn keys(&self) -> Vec<String> {
        self.v
            .as_object()
            .map(|m| m.keys().cloned().collect())
            .unwrap_or_default()
    }

    /// A nested object.
    pub fn obj(&self, key: &str) -> Rec<'a> {
        let v = self.value(key);
        assert!(
            v.is_object(),
            "{}: expected object, found {}",
            self.at(key),
            short(v)
        );
        Rec::new(v, self.at(key))
    }

    pub fn opt_obj(&self, key: &str) -> Option<Rec<'a>> {
        self.has(key).then(|| self.obj(key))
    }

    /// An array of objects (e.g. `steps`, `solves`).
    pub fn list(&self, key: &str) -> Vec<Rec<'a>> {
        let v = self.value(key);
        let arr = v
            .as_array()
            .unwrap_or_else(|| panic!("{}: expected array, found {}", self.at(key), short(v)));
        arr.iter()
            .enumerate()
            .map(|(i, e)| Rec::new(e, format!("{}[{i}]", self.at(key))))
            .collect()
    }

    pub fn str(&self, key: &str) -> &'a str {
        let v = self.value(key);
        v.as_str()
            .unwrap_or_else(|| panic!("{}: expected string, found {}", self.at(key), short(v)))
    }

    /// A double (hex bit pattern).
    pub fn f64(&self, key: &str) -> f64 {
        let s = self.str(key);
        super::hexf(s).unwrap_or_else(|e| panic!("{}: {e}", self.at(key)))
    }

    pub fn opt_f64(&self, key: &str) -> Option<f64> {
        self.has(key).then(|| self.f64(key))
    }

    /// A hash (`h_*` fields, `hash` objects): u64.
    pub fn hash(&self, key: &str) -> u64 {
        let s = self.str(key);
        super::hex64(s).unwrap_or_else(|e| panic!("{}: {e}", self.at(key)))
    }

    /// Any JSON integer, as i64 (use for seeds, sizes beyond HighsInt).
    pub fn i64(&self, key: &str) -> i64 {
        let v = self.value(key);
        v.as_i64()
            .unwrap_or_else(|| panic!("{}: expected integer, found {}", self.at(key), short(v)))
    }

    /// A HighsInt (i32 in the oracle build), enum or int.
    pub fn int(&self, key: &str) -> i32 {
        let x = self.i64(key);
        i32::try_from(x)
            .unwrap_or_else(|_| panic!("{}: {x} does not fit HighsInt (i32)", self.at(key)))
    }

    pub fn opt_int(&self, key: &str) -> Option<i32> {
        self.has(key).then(|| self.int(key))
    }

    /// A bool (JSON 0/1).
    pub fn bool(&self, key: &str) -> bool {
        match self.i64(key) {
            0 => false,
            1 => true,
            x => panic!("{}: expected bool 0/1, found {x}", self.at(key)),
        }
    }

    fn array(&self, key: &str) -> &'a Vec<Value> {
        let v = self.value(key);
        v.as_array()
            .unwrap_or_else(|| panic!("{}: expected array, found {}", self.at(key), short(v)))
    }

    /// `vf`: vector of doubles.
    pub fn f64s(&self, key: &str) -> Vec<f64> {
        self.array(key)
            .iter()
            .enumerate()
            .map(|(i, e)| {
                let s = e.as_str().unwrap_or_else(|| {
                    panic!(
                        "{}[{i}]: expected hex f64 string, found {}",
                        self.at(key),
                        short(e)
                    )
                });
                super::hexf(s).unwrap_or_else(|err| panic!("{}[{i}]: {err}", self.at(key)))
            })
            .collect()
    }

    /// `vi`: vector of HighsInt.
    pub fn ints(&self, key: &str) -> Vec<i32> {
        self.array(key)
            .iter()
            .enumerate()
            .map(|(i, e)| {
                e.as_i64()
                    .and_then(|x| i32::try_from(x).ok())
                    .unwrap_or_else(|| {
                        panic!(
                            "{}[{i}]: expected HighsInt, found {}",
                            self.at(key),
                            short(e)
                        )
                    })
            })
            .collect()
    }

    /// `vi8`: vector of int8_t (nonbasicFlag, nonbasicMove, pivot types).
    pub fn i8s(&self, key: &str) -> Vec<i8> {
        self.array(key)
            .iter()
            .enumerate()
            .map(|(i, e)| {
                e.as_i64()
                    .and_then(|x| i8::try_from(x).ok())
                    .unwrap_or_else(|| {
                        panic!("{}[{i}]: expected int8, found {}", self.at(key), short(e))
                    })
            })
            .collect()
    }

    /// The `HVector` object at `key`.
    pub fn hv(&self, key: &str) -> HVectorRec {
        HVectorRec::from_rec(&self.obj(key))
    }

    /// The `HighsSparseMatrix` object at `key`.
    pub fn mat(&self, key: &str) -> MatrixRec {
        MatrixRec::from_rec(&self.obj(key))
    }

    /// A `basis` object {basicIndex, nonbasicFlag, nonbasicMove}.
    pub fn basis(&self, key: &str) -> BasisRec {
        BasisRec::from_rec(&self.obj(key))
    }

    /// An `arrays` object (the 11 HEkk work/base arrays).
    pub fn arrays(&self, key: &str) -> WorkArraysRec {
        WorkArraysRec::from_rec(&self.obj(key))
    }

    /// The `lp` object of `ekk_solve_enter`.
    pub fn lp(&self, key: &str) -> LpRec {
        LpRec::from_rec(&self.obj(key))
    }

    /// The `invert` object (every `HFactor::getInvert()` array).
    pub fn invert(&self, key: &str) -> InvertRec {
        InvertRec::from_rec(&self.obj(key))
    }

    /// The `result` object of a factor `build` / `refactor` record.
    pub fn build_result(&self, key: &str) -> BuildResultRec {
        BuildResultRec::from_rec(&self.obj(key))
    }

    /// The `solves` list of a factor record.
    pub fn solves(&self, key: &str) -> Vec<SolveRec> {
        self.list(key).iter().map(SolveRec::from_rec).collect()
    }
}

/// A short rendering of a JSON value for error messages.
pub fn short(v: &Value) -> String {
    let s = v.to_string();
    if s.chars().count() > 120 {
        let head: String = s.chars().take(120).collect();
        format!("{head}... ({} chars)", s.len())
    } else {
        s
    }
}
